From 3a1615d21eaa84ef3690ce5e2fbdfaf6f6b16c1c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:12:18 +0100
Subject: [PATCH] shell: give newly connected screens the existing screen's
 wallpaper

A screen connected for the first time got a desktop with the default
wallpaper, so users had to set theirs again on every new monitor. Now a
new desktop copies the wallpaper of the activity's first screen instead.

BUG: 418027
---
 shell/shellcorona.cpp | 19 +++++++++++++++++++
 1 file changed, 19 insertions(+)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..ceab6859ec 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -1580,9 +1580,28 @@ Plasma::Containment *ShellCorona::createContainmentForActivity(const QString &ac
         plugin = defaultContainmentPlugin();
     }

+    const bool isNew = !containmentForScreen(screenNum, activity, QString());
+
     Plasma::Containment *containment = containmentForScreen(screenNum, activity, plugin, QVariantList());
     Q_ASSERT(containment);

+    if (isNew) {
+        // A new screen gets the wallpaper of the activity's lowest-numbered screen
+        Plasma::Containment *source = nullptr;
+        for (Plasma::Containment *cont : containments) {
+            if (!cont->destroyed() && cont->screen() >= 0 && (!source || cont->screen() < source->screen())) {
+                source = cont;
+            }
+        }
+        if (source && source != containment && !source->wallpaperPlugin().isEmpty()) {
+            KConfigGroup sourceWallpaper = source->config().group(u"Wallpaper"_s);
+            KConfigGroup wallpaper = containment->config().group(u"Wallpaper"_s);
+            wallpaper.deleteGroup();
+            sourceWallpaper.copyTo(&wallpaper);
+            containment->setWallpaperPlugin(source->wallpaperPlugin());
+        }
+    }
+
     return containment;
 }

